reviewed_production_functions.bound_from_approx:
fn bound_from_approx(prec: Precision, appr: &BigInt) -> BoundInfo {
    // Approximation values with magnitude <= 1 are within the allowed error
    // band, so they cannot certify sign or nonzero status.
    let magnitude = appr.magnitude();
    let magnitude_bits = magnitude.bits();
    if magnitude_bits <= 1 {
        BoundInfo::Unknown
    } else {
        let reaches_next_binade = magnitude.trailing_ones() == magnitude_bits;
        let msd = crate::verified::word::checked_bit_length_msd(
            magnitude_bits,
            if reaches_next_binade { 0 } else { 1 },
            false,
            prec,
        );
        // The closed one-unit interval [|a|-1, |a|+1] has one binary
        // exponent unless a is a power of two or one below the next power.
        // Inspect trailing bits instead of allocating endpoint integers.
        let exact_msd = msd.is_some()
            && magnitude.trailing_zeros() != Some(magnitude_bits - 1)
            && !reaches_next_binade;
        BoundInfo::with_sign_msd(appr.sign(), msd, exact_msd)
    }
}

reviewed_production_functions.store_cache_value:
fn store_cache_value(
    &self,
    signal: &Option<Signal>,
    p: Precision,
    value: BigInt,
) -> Result<(), Problem> {
    // Store only exact node approximation results, not temporary scaled
    // values. For shared constants this updates the process-wide cache so
    // every cloned constant wrapper and worker thread benefits.
    //
    // Kernels propagate failure before this method is called. Cancellation
    // may still arrive after a kernel completes; propagate that observation
    // while leaving previously completed cache entries intact.
    if should_stop(signal) || evaluation_exhausted() {
        return Err(Problem::Exhausted);
    }
    let approximation_bound = Self::bound_from_approx(p, &value);
    if approximation_bound != BoundInfo::Unknown {
        // Discover structural certificates before publishing a numerical
        // bound. Otherwise an approximation-first query can occupy an
        // uninitialized slot and hide an exact rational or root MSD.
        self.cheap_bound();
        if evaluation_exhausted() {
            return Err(Problem::Exhausted);
        }
        // A separated approximation may add a sign or magnitude to the
        // structural evidence. Atomic publication combines compatible
        // proofs without dropping an existing exact MSD or sign.
        self.internal.facts.publish_bound(approximation_bound);
    }
    if let Some(constant) = self.shared_constant_kind() {
        Self::store_shared_constant_cache_value(constant, p, value);
    } else {
        self.internal.store_cache_value(p, value);
    }
    Ok(())
}
